"use strict";
function openJavaRoom(){navigate({type:'javame',name:'Java ME 口袋实验室',url:'archaeo://javame'});}
function renderJavaRoom(){return `<section class="java-room"><header><small>JAVA ME / 真实字节码运行</small><h1>那颗 Java 图标，又亮起来了。</h1><p>浏览器内的 Java ME 虚拟机。内置本站编写的贪吃蛇、计算器、记事本，也可导入你有权使用的 JAR。</p><button data-world-channel="games">‹ 返回游戏厅</button><button data-phone-lab>口袋时光机</button></header><div class="java-runtime-shell"><iframe id="java-runtime" title="Java ME 口袋实验室" src="javame/?v=0.4.2" sandbox="allow-scripts allow-same-origin allow-downloads"></iframe></div><footer>运行内核基于 Mozilla PluotSorbet；组件许可证与对应源码可在实验室内下载。JAR 在本机内存中导入，不上传服务器。兼容性仍有限，高级控件、3D、音频与旧软件联网服务可能不可用。本站不提供商业游戏包。</footer></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-javame-room]');if(b){e.preventDefault();openJavaRoom();}});
